package br.com.fiap.bank.core.presentation;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.util.*; import br.com.fiap.bank.core.application.*; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(NaoEncontradoException.class) public ResponseEntity<Map<String,Object>> notFound(NaoEncontradoException e){return ResponseEntity.status(404).body(Map.of("erro","Não encontrado","mensagem",e.getMessage()));} @ExceptionHandler(ConflitoException.class) public ResponseEntity<Map<String,Object>> conflict(ConflitoException e){return ResponseEntity.status(409).body(Map.of("erro","Conflito","mensagem",e.getMessage()));} @ExceptionHandler(RequisicaoInvalidaException.class) public ResponseEntity<Map<String,Object>> invalid(RequisicaoInvalidaException e){return ResponseEntity.badRequest().body(Map.of("erro","Requisição inválida","mensagem",e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("erro","Dados inválidos","detalhes",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList()));} }
